-- ====================================================================
-- OZ-POS Database Schema — Postgres port of the fully-migrated SQLite
-- schema (20260813_init.sql + every incremental migration in the
-- crates/oz-core/src/migrations.rs registry, applied and dumped at
-- final state).
-- Generated by scripts/generate-pg-migration.py — DO NOT EDIT BY HAND.
-- Regenerate:  python3 scripts/generate-pg-migration.py
-- Drift guard: python3 scripts/generate-pg-migration.py --check
-- ====================================================================

CREATE TABLE IF NOT EXISTS audit_log (
    id          TEXT PRIMARY KEY,                          -- UUID v4
    user_id     TEXT NOT NULL,                             -- FK to users.id (nullable if action is from system)
    action      TEXT NOT NULL,                             -- e.g. "sale.void", "sale.refund", "settings.change", "login", "export"
    target_type TEXT,                                      -- e.g. "sale", "user", "setting"
    target_id   TEXT,                                      -- e.g. sale UUID, username, setting key
    details     TEXT DEFAULT '{}',                         -- JSON blob with action-specific metadata
    outcome     TEXT NOT NULL DEFAULT 'success',           -- "success" or "failure"
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS audit_review_checkpoints (
    id                           TEXT PRIMARY KEY,
    store_id                     TEXT NOT NULL,
    reviewer_user_id             TEXT NOT NULL,
    reviewed_at                  TEXT NOT NULL,             -- ISO-8601 review action time
    reviewed_through_created_at  TEXT NOT NULL,             -- newest entry.created_at covered
    reviewed_through_id          TEXT NOT NULL,             -- tie-breaker entry id covered
    created_at                   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS categories (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    colour     TEXT NOT NULL DEFAULT '#6366f1',
    created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, icon TEXT NOT NULL DEFAULT '');

CREATE TABLE IF NOT EXISTS currencies (
    code            TEXT PRIMARY KEY,          -- ISO-4217 alpha-3, e.g. "USD"
    numeric_code    TEXT NOT NULL,             -- ISO-4217 numeric, e.g. "840"
    name            TEXT NOT NULL,             -- Display name, e.g. "US Dollar"
    minor_exponent  BIGINT NOT NULL DEFAULT 2, -- Decimal places, e.g. 2 for USD
    symbol          TEXT NOT NULL DEFAULT '',  -- Currency symbol, e.g. "$"
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS hardware_profiles (
    terminal_id    TEXT PRIMARY KEY,
    profile_json   TEXT NOT NULL,
    schema_version BIGINT NOT NULL DEFAULT 1,
    updated_at     TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS inventory_locations (
    id          TEXT PRIMARY KEY,                            -- UUID v7
    name        TEXT NOT NULL,                               -- 'Store Inventory', 'Warehouse A'
    type        TEXT NOT NULL DEFAULT 'store'
                CHECK (type IN ('store', 'warehouse', 'transit', 'damaged', 'virtual')),
    description TEXT NOT NULL DEFAULT '',
    is_active   BIGINT NOT NULL DEFAULT 1,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_inventory_locations_name_unique
    ON inventory_locations(name) WHERE is_active = 1;

CREATE TABLE IF NOT EXISTS login_attempts (
    id          TEXT PRIMARY KEY,
    username    TEXT NOT NULL,
    attempted_at BIGINT NOT NULL  -- Unix epoch seconds
, device_id TEXT);

CREATE TABLE IF NOT EXISTS loyalty_tiers (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    min_points  BIGINT NOT NULL DEFAULT 0,
    points_per_unit BIGINT NOT NULL DEFAULT 10,
    colour      TEXT NOT NULL DEFAULT '#6b7280',
    sort_order  BIGINT NOT NULL DEFAULT 0,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, earn_multiplier_millionths BIGINT NOT NULL DEFAULT 1000000);

CREATE TABLE IF NOT EXISTS modifier_groups (
    id             TEXT PRIMARY KEY,
    name           TEXT NOT NULL,
    min_selections BIGINT NOT NULL DEFAULT 0 CHECK (min_selections >= 0),
    max_selections BIGINT NOT NULL DEFAULT 1 CHECK (max_selections >= 1),
    sort_order     BIGINT NOT NULL DEFAULT 0,
    created_at     TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at     TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    CHECK (max_selections >= min_selections)
);

CREATE TABLE IF NOT EXISTS offline_queue (
    id              TEXT PRIMARY KEY,
    action          TEXT NOT NULL,          -- e.g. "complete_sale", "void_sale"
    payload         TEXT NOT NULL,          -- JSON-serialized action data
    status          TEXT NOT NULL DEFAULT 'pending',  -- pending | synced | failed
    retry_count     BIGINT NOT NULL DEFAULT 0,
    last_error      TEXT,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    synced_at       TEXT
, tenant_id TEXT NOT NULL DEFAULT 'default', priority BIGINT NOT NULL DEFAULT 1);

CREATE TABLE IF NOT EXISTS processed_webhooks (
    event_id TEXT PRIMARY KEY,
    provider TEXT NOT NULL,   -- 'stripe' or 'square'
    received_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
    event_type TEXT           -- e.g. 'payment_intent.succeeded'
);

CREATE TABLE IF NOT EXISTS product_activity (
    id         TEXT PRIMARY KEY,
    sku        TEXT NOT NULL,
    event_type TEXT NOT NULL CHECK (event_type IN ('search', 'edit')),
    created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, tenant_id TEXT NOT NULL DEFAULT 'default');

CREATE TABLE IF NOT EXISTS promotions (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    -- 'percentage', 'fixed_amount', 'buy_x_get_y'
    promo_type  TEXT NOT NULL,
    -- For percentage: value is the percent (e.g., 10 = 10% off)
    -- For fixed_amount: value is in minor units
    -- For buy_x_get_y: value is the discount % on the free item
    value_minor BIGINT NOT NULL DEFAULT 0,
    -- Buy-X-get-Y: minimum quantity the customer must buy
    min_qty     BIGINT,
    -- Buy-X-get-Y: product SKU that must be purchased
    trigger_sku TEXT,
    -- Buy-X-get-Y: product SKU that gets the discount (empty = same as trigger)
    reward_sku  TEXT,
    -- Buy-X-get-Y: how many reward items the customer gets
    reward_qty  BIGINT DEFAULT 1,
    -- Time-limited: optional start/end
    starts_at   TEXT,
    ends_at     TEXT,
    -- Minimum order total in minor units for the promotion to apply
    min_order_minor BIGINT DEFAULT 0,
    -- Which product category this applies to (empty = all products)
    category_id TEXT,
    -- Whether this promotion is currently active
    active      BIGINT NOT NULL DEFAULT 1,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS roles (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,          -- e.g. "owner", "manager", "cashier"
    description TEXT NOT NULL DEFAULT '',
    permissions TEXT NOT NULL DEFAULT '[]',     -- JSON array of permission strings
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS setting_updated (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    key         TEXT    NOT NULL,
    value       TEXT    NOT NULL,
    terminal_id TEXT    NOT NULL DEFAULT 'unknown',
    version     BIGINT NOT NULL,
    created_at  TEXT    NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_setting_updated_unique_version
    ON setting_updated(key, terminal_id, version);

CREATE TABLE IF NOT EXISTS settings (
    key        TEXT PRIMARY KEY,
    value      TEXT NOT NULL DEFAULT '',
    updated_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS "stock_counts" (
    id           TEXT PRIMARY KEY,
    count_number TEXT NOT NULL UNIQUE,
    status       TEXT NOT NULL DEFAULT 'draft'
                 CHECK (status IN ('draft', 'in_progress', 'completed', 'cancelled')),
    count_type   TEXT NOT NULL DEFAULT 'full'
                 CHECK (count_type IN ('full', 'cyclic', 'spot')),
    notes        TEXT NOT NULL DEFAULT '',
    counted_by   TEXT,
    created_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    completed_at TEXT,
    updated_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));

CREATE TABLE IF NOT EXISTS stripe_customers (
    stripe_customer_id TEXT PRIMARY KEY,
    tenant_id          TEXT NOT NULL,
    updated_at         TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS suppliers (
    id          TEXT PRIMARY KEY NOT NULL,
    code        TEXT NOT NULL,
    name        TEXT NOT NULL,
    contact_person TEXT NOT NULL DEFAULT '',
    phone       TEXT NOT NULL DEFAULT '',
    email       TEXT NOT NULL DEFAULT '',
    address     TEXT NOT NULL DEFAULT '',
    tax_id      TEXT NOT NULL DEFAULT '',
    payment_terms TEXT NOT NULL DEFAULT '',
    notes       TEXT NOT NULL DEFAULT '',
    status      TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active', 'inactive')),
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_suppliers_code ON suppliers(code);

CREATE TABLE IF NOT EXISTS sync_applied_items (
    item_id    TEXT PRIMARY KEY,                     -- remote offline_queue item id
    action     TEXT NOT NULL,                        -- action applied (for diagnostics)
    applied_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS sync_pull_state (
    id         BIGINT PRIMARY KEY CHECK (id = 1),   -- single-row guard
    since      TEXT,                                  -- ISO-8601 anchor timestamp
    cursor     TEXT                                   -- opaque pagination cursor (P-3)
);

CREATE TABLE IF NOT EXISTS sync_remote_failures (
    item_id         TEXT PRIMARY KEY,
    action          TEXT NOT NULL,
    payload         TEXT NOT NULL,
    attempts        BIGINT NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    last_error      TEXT NOT NULL,
    first_failed_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    last_failed_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    dead_lettered   BIGINT NOT NULL DEFAULT 0 CHECK (dead_lettered IN (0, 1))
);

CREATE TABLE IF NOT EXISTS sync_terminals (
    terminal_id   TEXT PRIMARY KEY,
    -- SHA-256 hex digest of the device secret (never the plaintext).
    secret_hash   TEXT NOT NULL,
    label         TEXT NOT NULL DEFAULT '',
    tenant_id     TEXT,
    created_at    TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS tenant_plans (
    tenant_id   TEXT PRIMARY KEY,
    plan        TEXT NOT NULL DEFAULT 'free'
                CHECK (plan IN ('free', 'pro')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS tenant_subscription (
    tenant_id          TEXT PRIMARY KEY,
    tier_key           TEXT NOT NULL,        -- 'free', 'pro', 'premium', 'enterprise'
    status             TEXT NOT NULL,        -- 'active', 'past_due', 'canceled'
    expires_at         TEXT NULL,            -- ISO timestamp (NULL = lifetime/free)
    max_locations         BIGINT NOT NULL,
    max_pos_instances  BIGINT NOT NULL,     -- Per-store register limit
    allowed_types_json TEXT NOT NULL,        -- '["restaurant-pos", "store-pos", "admin"]'
    signature          TEXT NOT NULL,        -- RSA/HMAC signature from apps/cloud-server
    updated_at         TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, signed_payload TEXT NOT NULL DEFAULT '', api_key TEXT NOT NULL DEFAULT '');

CREATE TABLE IF NOT EXISTS user_preferences (
    user_id    TEXT NOT NULL,
    pref_key   TEXT NOT NULL,
    pref_value TEXT NOT NULL DEFAULT '',
    updated_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    PRIMARY KEY (user_id, pref_key)
);

CREATE TABLE IF NOT EXISTS workspace_types (
    key            TEXT PRIMARY KEY,
    name           TEXT NOT NULL,
    description    TEXT NOT NULL DEFAULT '',
    layout_mode    TEXT NOT NULL DEFAULT 'fullscreen',  -- 'fullscreen' | 'sidebar'
    icon           TEXT NOT NULL DEFAULT '',
    sort_order     BIGINT NOT NULL DEFAULT 0,
    accent_colour  TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS workspaces (
    id        TEXT PRIMARY KEY,
    key       TEXT NOT NULL UNIQUE,
    name      TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    icon      TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS sent_reports (
    tenant_id TEXT NOT NULL,
    period    TEXT NOT NULL,
    report_id TEXT NOT NULL,
    sent_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    PRIMARY KEY (tenant_id, period)
);

CREATE TABLE IF NOT EXISTS "kds_daily_counters" (
    date        TEXT NOT NULL,
    store_id    TEXT NOT NULL DEFAULT '',
    counter     BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (date, store_id)
);

CREATE TABLE IF NOT EXISTS media_assets (
    id          TEXT PRIMARY KEY,          -- UUID v7
    tenant_id   TEXT NOT NULL DEFAULT 'default',  -- RLS tenant scope
    owner_type  TEXT NOT NULL,             -- 'product' | 'category' | 'store' | 'kds'
    owner_id    TEXT NOT NULL,             -- FK to the owning entity
    file_path   TEXT NOT NULL,             -- relative path under the media root
    mime_type   TEXT NOT NULL,             -- e.g. image/jpeg
    content_hash TEXT,                     -- SHA-256 of file bytes (dedup), NULL until indexed
    width       BIGINT,                   -- pixel width (NULL until decoded)
    height      BIGINT,                   -- pixel height (NULL until decoded)
    size_bytes  BIGINT NOT NULL DEFAULT 0,
    original_name TEXT,                    -- user-supplied file name
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS edc_terminals (
    id              TEXT PRIMARY KEY,      -- UUID v7
    tenant_id       TEXT NOT NULL DEFAULT 'default',  -- RLS tenant scope
    name            TEXT NOT NULL,         -- "Front counter EDC"
    connection_type TEXT NOT NULL          -- 'wired' | 'wireless'
                    CHECK (connection_type IN ('wired', 'wireless')),
    transport       TEXT NOT NULL,         -- 'serial' | 'usb' | 'bluetooth' | 'tcp'
    address         TEXT NOT NULL,         -- device path / MAC / host:port
    vendor          TEXT,                  -- e.g. 'ingenico' | 'verifone' | 'pax'
    model           TEXT,
    is_active       BIGINT NOT NULL DEFAULT 1,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS payment_gateways (
    id           TEXT PRIMARY KEY,          -- UUID v7
    tenant_id    TEXT NOT NULL DEFAULT 'default',  -- RLS tenant scope
    name         TEXT NOT NULL,             -- 'stripe' | 'square' | 'midtrans' | 'paddle'
    is_active    BIGINT NOT NULL DEFAULT 1,
    config_json  TEXT NOT NULL DEFAULT '{}', -- gateway-specific keys (api key, sandbox flag, …)
    created_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    UNIQUE (tenant_id, name)
);

CREATE TABLE IF NOT EXISTS payment_settlements (
    id           TEXT PRIMARY KEY,          -- UUID v7
    tenant_id    TEXT NOT NULL DEFAULT 'default',  -- RLS tenant scope
    gateway      TEXT NOT NULL,             -- 'stripe' | 'square' | 'midtrans' | 'paddle'
    batch_id     TEXT NOT NULL,             -- gateway settlement/batch reference
    settled_at   TEXT,                      -- ISO-8601 when the gateway settled
    expected_minor BIGINT NOT NULL DEFAULT 0, -- expected amount (minor units)
    actual_minor   BIGINT NOT NULL DEFAULT 0, -- actual deposited amount (minor units)
    currency     TEXT NOT NULL DEFAULT 'USD',
    status       TEXT NOT NULL DEFAULT 'pending'
                 CHECK (status IN ('pending', 'matched', 'discrepancy', 'reconciled')),
    created_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS image_refs (
    tenant_id  TEXT NOT NULL,
    hash       TEXT NOT NULL,
    refcount   BIGINT NOT NULL DEFAULT 0,
    bytes      BIGINT NOT NULL DEFAULT 0,
    updated_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    PRIMARY KEY (tenant_id, hash)
);

CREATE TABLE IF NOT EXISTS image_push_queue (
    hash            TEXT NOT NULL PRIMARY KEY,
    size_bytes      BIGINT NOT NULL,
    attempts        BIGINT NOT NULL DEFAULT 0,
    next_attempt_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    enqueued_at     TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS outbox (
    id              TEXT PRIMARY KEY,
    topic           TEXT NOT NULL,
    payload         TEXT NOT NULL,
    status          TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'delivering', 'delivered', 'failed', 'dead_letter')),
    priority        BIGINT NOT NULL DEFAULT 0,
    max_attempts    BIGINT NOT NULL DEFAULT 5,
    attempts        BIGINT NOT NULL DEFAULT 0,
    next_attempt_at TEXT NOT NULL,       -- RFC 3339 timestamp
    created_at      TEXT NOT NULL,
    last_error      TEXT
);

CREATE TABLE IF NOT EXISTS snapshot_versions (
    tenant_id  TEXT PRIMARY KEY,
    version    BIGINT NOT NULL DEFAULT 0,
    updated_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS webhook_endpoints (
    id          TEXT PRIMARY KEY,
    tenant_id   TEXT NOT NULL DEFAULT 'default',
    url         TEXT NOT NULL,
    secret      TEXT NOT NULL,
    events      TEXT NOT NULL DEFAULT '["*"]',
    active      BIGINT NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS legal_entities (
    id                  TEXT PRIMARY KEY,
    tenant_id           TEXT NOT NULL,
    name                TEXT NOT NULL,
    legal_name          TEXT NOT NULL DEFAULT '',
    registration_number TEXT NOT NULL DEFAULT '',
    tax_id              TEXT NOT NULL DEFAULT '',
    status              TEXT NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active', 'inactive')),
    created_at          TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at          TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), country_code TEXT NOT NULL DEFAULT '', locale TEXT NOT NULL DEFAULT '', timezone TEXT NOT NULL DEFAULT '', currency TEXT NOT NULL DEFAULT '',
    UNIQUE (tenant_id, name)
);

CREATE TABLE IF NOT EXISTS "memos" (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL,
    author_user_id  TEXT NOT NULL,
    -- Author's role snapshot at publish time, so a later role change cannot
    -- retroactively lock the author out of stopping their own memo or grant a
    -- demoted user authority over a memo they no longer outrank.
    author_role     TEXT NOT NULL,
    title           TEXT NOT NULL,
    body            TEXT NOT NULL,
    status          TEXT NOT NULL DEFAULT 'draft'
                    CHECK (status IN ('draft','published','expired','stopped','archived')),
    duration        TEXT NOT NULL DEFAULT '24h'
                    CHECK (duration IN ('12h','24h','3d','7d','30d')),
    revision        BIGINT NOT NULL DEFAULT 1,
    published_at    TEXT,
    expires_at      TEXT,
    stopped_at      TEXT,
    stopped_by      TEXT,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, archived_at TEXT);

CREATE TABLE IF NOT EXISTS topology_revisions (
    id                      TEXT PRIMARY KEY,
    branch_id               TEXT NOT NULL DEFAULT '',
    revision                BIGINT NOT NULL,

    -- Author-chosen "what changed and why" (ADR #46 §6). Optional at the UI,
    -- empty by default; this column is the difference between a list of
    -- timestamps and an actual history.
    change_note             TEXT NOT NULL DEFAULT '',

    -- The full graph envelope, byte-identical to what was written to `settings`
    -- for this revision, so a revision is self-contained and needs no
    -- reconstruction. NULL means DEFLATED (ADR #46 §4): the record of who, when,
    -- and why is kept permanently, the restorable snapshot is not. Every read
    -- path that offers a restore must check this for NULL and say
    -- "record only — snapshot pruned" rather than offering a restore that fails.
    diagram                 TEXT,

    -- Workspace-diff COUNTS, not workspace rows (ADR #46 §2). Apply already has
    -- these in hand at commands.rs:272-274. They let a history row explain
    -- itself — "this Apply archived 3 workspaces" — without duplicating another
    -- table's contents or growing without bound.
    workspace_creations     BIGINT NOT NULL DEFAULT 0,
    workspace_updates       BIGINT NOT NULL DEFAULT 0,
    workspace_archives      BIGINT NOT NULL DEFAULT 0,
    node_count              BIGINT NOT NULL DEFAULT 0,
    wire_count              BIGINT NOT NULL DEFAULT 0,

    -- Which SEMANTICS CONTRACT this revision was authored under, stamped from
    -- `oz_core::topology::TOPOLOGY_CONTRACT_SCHEMA_VERSION` at write time.
    --
    -- Named for the axis it holds, deliberately. This repo maintains two
    -- version axes that model.rs:273-285 warns "must never be conflated": the
    -- ENVELOPE version (shape of a saved diagram, currently 1, already stored
    -- inside `diagram` itself) and the CONTRACT version (the pairing table,
    -- which ADR #45 moved 1 -> 2). ADR #46 §7's question — "can this revision
    -- still be restored?" — is answered by the contract axis, so that is what
    -- is recorded here. The envelope version would be a constant column that
    -- duplicates a field already inside the JSON.
    contract_schema_version BIGINT NOT NULL,

    -- Pinned revisions are exempt from both pruning and deflation (ADR #46 §4).
    -- This is what makes the table a DEPLOY history rather than a scratch pad:
    -- a known-good graph stays restorable however busy the branch gets after it.
    pinned                  BIGINT NOT NULL DEFAULT 0 CHECK (pinned IN (0, 1)),

    published_at            TEXT NOT NULL,
    published_by            TEXT NOT NULL,
    -- Stamped by the write path; NOT yet added to RLS_TABLES in
    -- scripts/generate-pg-migration.py. That mirrors memo_revisions exactly —
    -- enabling RLS is a policy decision the repo keeps separate from schema, and
    -- the generator surfaces uncovered tenant_id tables as a visible comment
    -- rather than failing (ADR #46 §9).
    tenant_id               TEXT NOT NULL DEFAULT 'default',

    UNIQUE (branch_id, revision)
);

CREATE TABLE IF NOT EXISTS over_quota_markers (
    id            BIGINT PRIMARY KEY,
    resource_id   TEXT    NOT NULL,
    resource_type TEXT    NOT NULL,
    dimension     TEXT    NOT NULL,
    severity      TEXT    NOT NULL CHECK (severity IN ('over', 'at')),
    "limit"       BIGINT,
    current       BIGINT NOT NULL,
    marked_at     TEXT    NOT NULL,
    tenant_id     TEXT    NOT NULL DEFAULT 'default'
);

CREATE TABLE IF NOT EXISTS local_payment_methods (
    id          TEXT PRIMARY KEY,
    tenant_id   TEXT NOT NULL DEFAULT 'default',
    scope_type  TEXT NOT NULL CHECK (scope_type IN ('legal_entity', 'location')),
    scope_id    TEXT NOT NULL,
    rail_code   TEXT NOT NULL,
    label       TEXT NOT NULL,
    is_enabled  BIGINT NOT NULL DEFAULT 1,
    parameters  TEXT NOT NULL DEFAULT '{}',
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL,
    UNIQUE (scope_type, scope_id, rail_code)
);

CREATE TABLE IF NOT EXISTS receipt_formats (
    id             TEXT PRIMARY KEY,
    tenant_id      TEXT NOT NULL DEFAULT 'default',
    scope_type     TEXT NOT NULL CHECK (scope_type IN ('legal_entity', 'workspace', 'terminal')),
    scope_id       TEXT NOT NULL,
    config         TEXT NOT NULL DEFAULT '{}',
    paper_width_mm BIGINT CHECK (paper_width_mm IS NULL OR (paper_width_mm BETWEEN 20 AND 120)),
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    UNIQUE (scope_type, scope_id)
);

CREATE TABLE IF NOT EXISTS sale_idempotency (
    tenant_id  TEXT NOT NULL DEFAULT 'default',
    key        TEXT,
    sale_id    TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_sale_idempotency_tenant_key
    ON sale_idempotency(tenant_id, key);

CREATE TABLE IF NOT EXISTS sync_conflicts (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL DEFAULT 'default',
    entity_type       TEXT NOT NULL,
    entity_id         TEXT NOT NULL,
    local_terminal_id TEXT NOT NULL,
    local_vector      TEXT NOT NULL,
    remote_vector     TEXT NOT NULL,
    local_payload     TEXT NOT NULL,
    remote_payload    TEXT NOT NULL,
    severity          TEXT NOT NULL
                      CHECK (severity IN ('high', 'medium', 'low')),
    status            TEXT NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open', 'resolved', 'dismissed')),
    resolution        TEXT,
    resolved_by       TEXT,
    resolved_at       TEXT,
    created_at        TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS sync_entity_vectors (
    tenant_id   TEXT NOT NULL DEFAULT 'default',
    entity_type TEXT NOT NULL,
    entity_id   TEXT NOT NULL,
    vector      TEXT NOT NULL,
    -- Last body seen for this entity. Kept so the field-wise merge policy can
    -- tell whether two concurrent customer edits touched the same fields;
    -- without it every such comparison would have to be answered "overlap"
    -- and every profile conflict would need a human. Not a payload store of
    -- record: `offline_queue` remains that.
    last_payload TEXT NOT NULL DEFAULT '',
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    PRIMARY KEY (tenant_id, entity_type, entity_id)
);

CREATE TABLE IF NOT EXISTS midtrans_transactions (
    order_id     TEXT PRIMARY KEY,
    tenant_id    TEXT NOT NULL,
    sale_id      TEXT NOT NULL,
    amount_minor BIGINT NOT NULL,
    currency     TEXT NOT NULL DEFAULT 'IDR',
    status       TEXT NOT NULL DEFAULT 'issued',
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS exchange_rates (
    id              TEXT PRIMARY KEY,
    from_currency   TEXT NOT NULL REFERENCES currencies(code),
    to_currency     TEXT NOT NULL REFERENCES currencies(code),
    source          TEXT NOT NULL DEFAULT 'manual', -- manual, api, etc.
    effective_date  TEXT NOT NULL,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), rate_millionths BIGINT NOT NULL DEFAULT 0,
    UNIQUE (from_currency, to_currency, effective_date)
);

CREATE TABLE IF NOT EXISTS active_carts (
    id              TEXT PRIMARY KEY NOT NULL,
    cart_data       TEXT NOT NULL,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, deduction_location_id TEXT
    REFERENCES inventory_locations(id) ON DELETE RESTRICT, location_override_at TEXT);

CREATE TABLE IF NOT EXISTS held_carts (
    id              TEXT PRIMARY KEY,
    label           TEXT NOT NULL,
    cart_data       TEXT NOT NULL,
    item_count      BIGINT NOT NULL DEFAULT 0,
    total_minor     BIGINT NOT NULL DEFAULT 0,
    currency        TEXT NOT NULL DEFAULT 'USD',
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, bill_type TEXT NOT NULL DEFAULT 'hold', customer_name TEXT, deduction_location_id TEXT
    REFERENCES inventory_locations(id) ON DELETE RESTRICT);

CREATE TABLE IF NOT EXISTS modifiers (
    id             TEXT PRIMARY KEY,
    group_id       TEXT NOT NULL REFERENCES modifier_groups(id) ON DELETE CASCADE,
    name           TEXT NOT NULL,
    price_minor    BIGINT NOT NULL DEFAULT 0 CHECK (price_minor >= 0),
    sort_order     BIGINT NOT NULL DEFAULT 0,
    is_default     BIGINT NOT NULL DEFAULT 0,
    created_at     TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at     TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS "users" (
    id          TEXT PRIMARY KEY,
    username    TEXT NOT NULL,
    pin_hash    TEXT NOT NULL,
    display_name TEXT NOT NULL,
    role_id     TEXT NOT NULL REFERENCES roles(id),
    is_active   BIGINT NOT NULL DEFAULT 1,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    tenant_id TEXT NOT NULL DEFAULT 'default',
    date_of_birth TEXT,
    phone TEXT,
    national_id_type TEXT,
    national_id TEXT,
    email TEXT,
    monthly_take_home_minor BIGINT,
    emergency_contact_name TEXT,
    emergency_contact_phone TEXT,
    job_title TEXT NOT NULL DEFAULT '',
    notes TEXT NOT NULL DEFAULT '',
    address TEXT,
    language TEXT,
    avatar TEXT,
    tax_id TEXT,
    national_id_expires_at TEXT,
    emergency_contact_relationship TEXT,
    hire_date TEXT,
    national_id_hash TEXT
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_users_email ON users(email);

CREATE UNIQUE INDEX IF NOT EXISTS idx_users_national_id ON users(national_id);

CREATE UNIQUE INDEX IF NOT EXISTS idx_users_national_id_hash ON users(national_id_hash);

CREATE UNIQUE INDEX IF NOT EXISTS idx_users_tenant_username ON users(tenant_id, username);

CREATE TABLE IF NOT EXISTS "stock_adjustments" (
    id            TEXT PRIMARY KEY,
    count_id      TEXT REFERENCES "stock_counts"(id) ON DELETE SET NULL,
    sku           TEXT NOT NULL,
    product_name  TEXT NOT NULL DEFAULT '',
    previous_qty  BIGINT NOT NULL DEFAULT 0 CHECK (previous_qty >= 0),
    adjusted_qty  BIGINT NOT NULL DEFAULT 0 CHECK (adjusted_qty >= 0),
    reason        TEXT NOT NULL DEFAULT '',
    created_by    TEXT,
    created_at    TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS "stock_count_lines" (
    id           TEXT PRIMARY KEY,
    count_id     TEXT NOT NULL REFERENCES "stock_counts"(id) ON DELETE CASCADE,
    sku          TEXT NOT NULL,
    product_name TEXT NOT NULL DEFAULT '',
    expected_qty BIGINT NOT NULL DEFAULT 0 CHECK (expected_qty >= 0),
    counted_qty  BIGINT CHECK (counted_qty IS NULL OR counted_qty >= 0),
    difference   BIGINT NOT NULL DEFAULT 0,
    notes        TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS role_workspace_types (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_id   TEXT NOT NULL REFERENCES roles(id),
    type_key  TEXT NOT NULL REFERENCES workspace_types(key),
    UNIQUE(role_id, type_key)
);

CREATE TABLE IF NOT EXISTS workspace_type_screens (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type_key    TEXT NOT NULL REFERENCES workspace_types(key),
    screen_key  TEXT NOT NULL,
    sort_order  BIGINT NOT NULL DEFAULT 0,
    UNIQUE(type_key, screen_key)
);

CREATE TABLE IF NOT EXISTS role_workspaces (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_id       TEXT NOT NULL REFERENCES roles(id),
    workspace_key TEXT NOT NULL REFERENCES workspaces(key),
    UNIQUE(role_id, workspace_key)
);

CREATE TABLE IF NOT EXISTS workspace_screens (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_key TEXT NOT NULL REFERENCES workspaces(key),
    screen_key    TEXT NOT NULL,
    label         TEXT NOT NULL DEFAULT '',
    sort_order    BIGINT NOT NULL DEFAULT 0,
    UNIQUE(workspace_key, screen_key)
);

CREATE TABLE IF NOT EXISTS media_thumbnails (
    id          TEXT PRIMARY KEY,          -- UUID v7
    tenant_id   TEXT NOT NULL DEFAULT 'default',  -- RLS tenant scope
    asset_id    TEXT NOT NULL,             -- FK to media_assets
    preset      TEXT NOT NULL,             -- 'icon' | 'small' | 'medium' | 'large'
    file_path   TEXT NOT NULL,             -- relative path under the media root
    width       BIGINT NOT NULL,
    height      BIGINT NOT NULL,
    size_bytes  BIGINT NOT NULL DEFAULT 0,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    FOREIGN KEY (asset_id) REFERENCES media_assets(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "locations" (
    id          TEXT PRIMARY KEY,                                   -- "default" or UUID for additional stores
    name        TEXT NOT NULL,
    address     TEXT DEFAULT '',
    tax_id      TEXT DEFAULT '',
    currency    TEXT NOT NULL DEFAULT 'USD',
    timezone    TEXT NOT NULL DEFAULT 'UTC',
    is_primary  BIGINT NOT NULL DEFAULT 0,                        -- exactly one store is the primary
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, tenant_id TEXT NOT NULL DEFAULT 'default', legal_entity_id TEXT
    REFERENCES legal_entities(id) ON DELETE RESTRICT, locale TEXT NOT NULL DEFAULT '', ticket_prefix TEXT NOT NULL DEFAULT '');

CREATE UNIQUE INDEX IF NOT EXISTS idx_locations_primary
    ON locations(is_primary) WHERE is_primary = 1;

CREATE UNIQUE INDEX IF NOT EXISTS idx_locations_tenant_ticket_prefix
    ON locations (tenant_id, ticket_prefix)
    WHERE ticket_prefix <> '';

CREATE TABLE IF NOT EXISTS fiscal_schemes (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL DEFAULT 'default',
    legal_entity_id TEXT NOT NULL REFERENCES legal_entities(id),
    scheme_code     TEXT NOT NULL,
    name            TEXT NOT NULL,
    parameters      TEXT NOT NULL DEFAULT '{}',
    is_active       BIGINT NOT NULL DEFAULT 1,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "document_number_sequences" (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL DEFAULT 'default',
    legal_entity_id TEXT NOT NULL REFERENCES legal_entities(id),
    document_kind   TEXT NOT NULL CHECK (document_kind IN ('receipt', 'invoice')),
    prefix          TEXT NOT NULL DEFAULT '',
    current_value   BIGINT NOT NULL DEFAULT 0,
    reset_period    TEXT NOT NULL DEFAULT 'never',
    period_key      TEXT NOT NULL DEFAULT '',
    padding         BIGINT NOT NULL DEFAULT 0,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    UNIQUE (legal_entity_id, document_kind)
);

CREATE TABLE IF NOT EXISTS memo_revisions (
    id            TEXT PRIMARY KEY,
    memo_id       TEXT NOT NULL REFERENCES memos(id) ON DELETE CASCADE,
    revision      BIGINT NOT NULL,
    title         TEXT NOT NULL,
    body          TEXT NOT NULL,
    published_at  TEXT NOT NULL,
    published_by  TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'default',
    UNIQUE (memo_id, revision)
);

CREATE TABLE IF NOT EXISTS assignments (
    user_id         TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    role_id         TEXT NOT NULL REFERENCES roles(id),
    scope_mode      TEXT NOT NULL DEFAULT 'global' CHECK (scope_mode IN ('global', 'scoped')),
    branch_scope    TEXT NOT NULL DEFAULT 'all'  CHECK (branch_scope IN ('all', 'list')),
    workspace_scope TEXT NOT NULL DEFAULT 'all'  CHECK (workspace_scope IN ('all', 'list')),
    expires_at      TEXT,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, scope_type TEXT
    NOT NULL DEFAULT 'organization'
    CHECK (scope_type IN ('organization', 'legal_entity', 'location')), scope_id TEXT);

CREATE TABLE IF NOT EXISTS gift_cards (
    id                      TEXT PRIMARY KEY,
    card_number             TEXT UNIQUE NOT NULL,
    pin                     TEXT NOT NULL DEFAULT '',
    initial_balance_minor   BIGINT NOT NULL DEFAULT 0,
    current_balance_minor   BIGINT NOT NULL DEFAULT 0,
    currency                TEXT NOT NULL DEFAULT 'IDR',
    status                  TEXT NOT NULL DEFAULT 'active'
                            CHECK (status IN ('active', 'frozen', 'redeemed', 'expired')),
    issued_to               TEXT NOT NULL DEFAULT '',
    issue_date              TEXT NOT NULL,
    expiry_date             TEXT,
    created_by              TEXT REFERENCES users(id),
    updated_at              TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS purchase_orders (
    id              TEXT PRIMARY KEY NOT NULL,
    po_number       TEXT NOT NULL,
    supplier_id     TEXT NOT NULL REFERENCES suppliers(id),
    status          TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft', 'pending', 'approved', 'received', 'cancelled')),
    order_date      TEXT NOT NULL,
    expected_date   TEXT NOT NULL DEFAULT '',
    received_date   TEXT,
    subtotal_minor  BIGINT NOT NULL DEFAULT 0,
    tax_minor       BIGINT NOT NULL DEFAULT 0,
    total_minor     BIGINT NOT NULL DEFAULT 0,
    notes           TEXT NOT NULL DEFAULT '',
    created_by      TEXT REFERENCES users(id),
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
, location_id TEXT
    REFERENCES inventory_locations(id) ON DELETE RESTRICT);

CREATE UNIQUE INDEX IF NOT EXISTS idx_purchase_orders_po_number ON purchase_orders(po_number);

CREATE TABLE IF NOT EXISTS user_workspaces (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    ws_key     TEXT NOT NULL REFERENCES workspaces(key) ON DELETE CASCADE,
    created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    UNIQUE(user_id, ws_key)
);

CREATE TABLE IF NOT EXISTS "customers" (
    id              TEXT PRIMARY KEY,
    name            TEXT NOT NULL,
    email           TEXT,
    phone           TEXT,
    loyalty_points  BIGINT NOT NULL DEFAULT 0,
    total_spent_minor BIGINT NOT NULL DEFAULT 0,
    currency        TEXT NOT NULL DEFAULT 'USD',
    notes           TEXT NOT NULL DEFAULT '',
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    store_id        TEXT REFERENCES "locations"(id) ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE TABLE IF NOT EXISTS terminals (
    id              TEXT PRIMARY KEY,
    name            TEXT NOT NULL,
    device_id       TEXT NOT NULL UNIQUE,
    terminal_secret TEXT,                   -- optional shared secret for sync auth
    is_active       BIGINT NOT NULL DEFAULT 1,
    last_seen_at    TEXT,
    metadata        TEXT,                   -- JSON blob for extra info
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, bound_location_id TEXT REFERENCES "locations"(id), bound_instance_id TEXT, binding_signature TEXT, tenant_id TEXT NOT NULL DEFAULT 'default');

CREATE TABLE IF NOT EXISTS "user_location_access" (
    user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    location_id     TEXT NOT NULL REFERENCES "locations"(id)
                              ON DELETE RESTRICT
                              ON UPDATE CASCADE,
    access_level TEXT NOT NULL DEFAULT 'operator',
    created_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), tenant_id TEXT NOT NULL DEFAULT 'default',
    UNIQUE(user_id, location_id)
);

CREATE TABLE IF NOT EXISTS "workspace_instances" (
    id          TEXT PRIMARY KEY,
    type_key    TEXT NOT NULL REFERENCES workspace_types(key),
    location_id    TEXT NOT NULL REFERENCES "locations"(id)
                              ON DELETE RESTRICT
                              ON UPDATE CASCADE,
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    colour      TEXT,
    status      TEXT NOT NULL DEFAULT 'active',
    last_accessed_at TEXT,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, bound_location_id TEXT
    REFERENCES inventory_locations(id) ON DELETE RESTRICT, purpose_key TEXT NOT NULL DEFAULT 'general');

CREATE TABLE IF NOT EXISTS "products" (
    id          TEXT PRIMARY KEY,
    sku         TEXT NOT NULL,
    name        TEXT NOT NULL,
    price_minor BIGINT NOT NULL CHECK (price_minor >= 0),
    currency    TEXT NOT NULL,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    category_id TEXT REFERENCES categories(id),
    barcode     TEXT,
    price_updated_at TEXT DEFAULT '',
    track_serial BIGINT NOT NULL DEFAULT 0,
    product_type TEXT NOT NULL DEFAULT 'retail',
    cost_minor  BIGINT NOT NULL DEFAULT 0,
    version     BIGINT NOT NULL DEFAULT 1,
    store_id    TEXT REFERENCES "locations"(id) ON DELETE SET NULL ON UPDATE CASCADE,
    tenant_id   TEXT NOT NULL DEFAULT 'default',
    kitchen_zone TEXT,
    brand TEXT,
    rack_location TEXT,
    notes TEXT,
    unit TEXT,
    is_active BIGINT NOT NULL DEFAULT 1,
    default_supplier_id TEXT REFERENCES suppliers(id),
    popularity_score DOUBLE PRECISION NOT NULL DEFAULT 0
, image_hash TEXT);

CREATE UNIQUE INDEX IF NOT EXISTS idx_products_tenant_sku ON products(tenant_id, sku);

CREATE UNIQUE INDEX IF NOT EXISTS uq_products_barcode ON products(barcode);

CREATE TABLE IF NOT EXISTS memo_locations (
    memo_id      TEXT NOT NULL REFERENCES memos(id) ON DELETE CASCADE,
    location_id  TEXT NOT NULL REFERENCES locations(id) ON DELETE RESTRICT,
    -- Carried from the memo (same denormalization `memo_recipients` uses) so
    -- every targeting/delivery row can prove its tenant without a join.
    tenant_id    TEXT NOT NULL DEFAULT 'default',
    PRIMARY KEY (memo_id, location_id)
);

CREATE TABLE IF NOT EXISTS "tax_rates" (
    id              TEXT PRIMARY KEY,
    name            TEXT NOT NULL,
    rate_bps        BIGINT NOT NULL CHECK (rate_bps >= 0),
    is_default      BIGINT NOT NULL DEFAULT 0,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    is_inclusive    BIGINT NOT NULL DEFAULT 0,
    tenant_id       TEXT NOT NULL DEFAULT 'default',
    is_active       BIGINT NOT NULL DEFAULT 1,
    legal_entity_id TEXT REFERENCES legal_entities(id) ON DELETE RESTRICT,
    location_id     TEXT REFERENCES locations(id) ON DELETE RESTRICT,
    effective_from  TEXT,
    effective_to    TEXT, rounding_mode TEXT NOT NULL DEFAULT ''
    CHECK (rounding_mode IN ('', 'half_up', 'truncate')),
    -- One scope, never both: see the header. NULL means "not scoped at this
    -- tier", so (NULL, NULL) is the tenant-global row and stays legal.
    CHECK (legal_entity_id IS NULL OR location_id IS NULL)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_tax_rates_default_entity
    ON tax_rates(tenant_id, legal_entity_id)
    WHERE is_default = 1
      AND legal_entity_id IS NOT NULL
      AND location_id IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_tax_rates_default_location
    ON tax_rates(tenant_id, location_id)
    WHERE is_default = 1
      AND location_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_tax_rates_default_tenant_global
    ON tax_rates(tenant_id)
    WHERE is_default = 1
      AND legal_entity_id IS NULL
      AND location_id IS NULL;

CREATE TABLE IF NOT EXISTS assignment_branches (
    assignment_user_id TEXT NOT NULL REFERENCES assignments(user_id) ON DELETE CASCADE,
    branch_id          TEXT NOT NULL,
    PRIMARY KEY (assignment_user_id, branch_id)
);

CREATE TABLE IF NOT EXISTS assignment_workspaces (
    assignment_user_id TEXT NOT NULL REFERENCES assignments(user_id) ON DELETE CASCADE,
    workspace_key      TEXT NOT NULL REFERENCES workspaces(key) ON DELETE CASCADE,
    PRIMARY KEY (assignment_user_id, workspace_key)
);

CREATE TABLE IF NOT EXISTS purchase_order_lines (
    id                TEXT PRIMARY KEY NOT NULL,
    po_id             TEXT NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE,
    sku               TEXT NOT NULL DEFAULT '',
    product_name      TEXT NOT NULL DEFAULT '',
    qty               BIGINT NOT NULL DEFAULT 0,
    unit_cost_minor   BIGINT NOT NULL DEFAULT 0,
    line_total_minor  BIGINT NOT NULL DEFAULT 0
, received_qty BIGINT NOT NULL DEFAULT 0, damaged_qty  BIGINT NOT NULL DEFAULT 0);

CREATE TABLE IF NOT EXISTS payables (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL,
    supplier_id     TEXT NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT,
    -- Optional link to the originating purchase order. NULL for a payable
    -- raised outside a PO (e.g. stock added directly at the register).
    po_id           TEXT REFERENCES purchase_orders(id) ON DELETE SET NULL,
    -- Free-text origin tag ('po_receive', 'stock_add', 'manual', …). Not an
    -- enum: entry points are expected to grow, and this is a display/audit
    -- label, not a state machine.
    source          TEXT NOT NULL DEFAULT 'manual',
    reference       TEXT NOT NULL DEFAULT '',   -- supplier's invoice / bill no.
    amount_minor    BIGINT NOT NULL CHECK (amount_minor >= 0),
    paid_minor      BIGINT NOT NULL DEFAULT 0 CHECK (paid_minor >= 0),
    currency        TEXT NOT NULL DEFAULT 'IDR',
    due_date        TEXT,                        -- ISO date (YYYY-MM-DD); NULL = open-ended
    status          TEXT NOT NULL DEFAULT 'open'
                    CHECK (status IN ('open','partial','paid','written_off')),
    note            TEXT NOT NULL DEFAULT '',
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    settled_at      TEXT,
    written_off_at  TEXT,
    -- Never pay more than owed; the store rejects over-payment before here.
    CHECK (paid_minor <= amount_minor)
);

CREATE TABLE IF NOT EXISTS loyalty_accounts (
    id          TEXT PRIMARY KEY,
    customer_id TEXT NOT NULL UNIQUE REFERENCES customers(id),
    points      BIGINT NOT NULL DEFAULT 0,
    lifetime_points BIGINT NOT NULL DEFAULT 0,
    tier_id     TEXT REFERENCES loyalty_tiers(id),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS "sales" (
    id                  TEXT PRIMARY KEY,
    total_minor         BIGINT NOT NULL,
    currency            TEXT NOT NULL,
    line_count          BIGINT NOT NULL CHECK (line_count >= 0),
    status              TEXT NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active', 'pending', 'completed', 'voided', 'refunded')),
    created_at          TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at          TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    payment_method      TEXT,
    tendered_minor      BIGINT,
    discount_percent    BIGINT NOT NULL DEFAULT 0,
    discount_label      TEXT,
    user_id             TEXT,
    subtotal_minor      BIGINT NOT NULL DEFAULT 0,
    tax_total_minor     BIGINT NOT NULL DEFAULT 0,
    customer_id         TEXT REFERENCES customers(id),
    version             BIGINT NOT NULL DEFAULT 1,
    store_id            TEXT REFERENCES "locations"(id) ON DELETE SET NULL ON UPDATE CASCADE,
    deduction_locations TEXT,
    pending_expires_at  TEXT,
    payment_reference   TEXT,
    captured_at         TEXT
, tenant_id TEXT NOT NULL DEFAULT 'default', base_currency TEXT, base_total_minor BIGINT, tender_rate_millionths BIGINT, tip_minor BIGINT NOT NULL DEFAULT 0, service_charge_minor BIGINT NOT NULL DEFAULT 0, statutory_number TEXT, tax_estimate_note TEXT);

CREATE TABLE IF NOT EXISTS inventory_shifts (
    id          TEXT PRIMARY KEY,                              -- UUID v7
    user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    location_id TEXT NOT NULL REFERENCES inventory_locations(id) ON DELETE RESTRICT,
    terminal_id TEXT REFERENCES terminals(id),                -- nullable; terminal that opened the shift
    started_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    ended_at    TEXT,                                          -- nullable; non-null when status = 'ended'
    status      TEXT NOT NULL DEFAULT 'active'
                CHECK (status IN ('active', 'ended')),
    notes       TEXT NOT NULL DEFAULT '',
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_inv_shifts_active_per_user_location
    ON inventory_shifts(user_id, location_id) WHERE status = 'active';

CREATE TABLE IF NOT EXISTS shifts (
    id                    TEXT PRIMARY KEY,
    user_id               TEXT NOT NULL REFERENCES users(id),
    terminal_id           TEXT REFERENCES terminals(id),
    opened_at             TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    closed_at             TEXT,
    opening_balance_minor BIGINT NOT NULL DEFAULT 0,
    closing_balance_minor BIGINT,                     -- counted cash at close
    expected_cash_minor   BIGINT,                     -- opening + cash sales - cash payouts
    cash_difference_minor BIGINT,                     -- closing - expected (positive = over, negative = short)
    total_sales_minor     BIGINT NOT NULL DEFAULT 0,  -- total sales amount during shift
    total_cash_minor      BIGINT NOT NULL DEFAULT 0,  -- cash sales amount
    total_card_minor      BIGINT NOT NULL DEFAULT 0,  -- card sales amount
    total_other_minor     BIGINT NOT NULL DEFAULT 0,  -- other payment method sales
    total_voids_minor     BIGINT NOT NULL DEFAULT 0,  -- voided amount
    total_refunds_minor   BIGINT NOT NULL DEFAULT 0,  -- refunded amount
    notes                 TEXT NOT NULL DEFAULT '',
    status                TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
    created_at            TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at            TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, total_payouts_minor BIGINT NOT NULL DEFAULT 0);

CREATE TABLE IF NOT EXISTS "stock_transfers" (
    id                     TEXT PRIMARY KEY,
    transfer_number        TEXT NOT NULL UNIQUE,
    status                 TEXT NOT NULL DEFAULT 'draft'
                           CHECK (status IN (
                               'draft',
                               'pending',
                               'in_transit',
                               'received',
                               'received_partial',
                               'cancelled'
                           )),
    source_location_old    TEXT,
    destination_location_old TEXT,
    source_location_id     TEXT NOT NULL DEFAULT '01926b3a-0000-7000-8000-000000000001'
                           REFERENCES inventory_locations(id) ON DELETE RESTRICT,
    destination_location_id TEXT NOT NULL DEFAULT '01926b3a-0000-7000-8000-000000000001'
                           REFERENCES inventory_locations(id) ON DELETE RESTRICT,
    source_terminal_id     TEXT REFERENCES terminals(id),
    destination_terminal_id TEXT REFERENCES terminals(id),
    notes                  TEXT NOT NULL DEFAULT '',
    created_by             TEXT NOT NULL,
    received_by            TEXT,
    created_at             TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    sent_at                TEXT,
    received_at            TEXT,
    updated_at             TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS terminal_feature_overrides (
    terminal_id TEXT NOT NULL REFERENCES terminals(id) ON DELETE CASCADE,
    feature     TEXT NOT NULL,
    enabled     BIGINT NOT NULL DEFAULT 1,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    PRIMARY KEY (terminal_id, feature)
);

CREATE TABLE IF NOT EXISTS terminal_profiles (
    terminal_id TEXT PRIMARY KEY REFERENCES terminals(id) ON DELETE CASCADE,
    profile_type TEXT NOT NULL DEFAULT 'unrestricted'
        CHECK (profile_type IN ('counter_pos', 'kds_kiosk', 'customer_display', 'unrestricted')),
    locked_screen TEXT,
    updated_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS kds_devices (
    id                  TEXT PRIMARY KEY,          -- UUID v7
    name                TEXT NOT NULL,             -- "Kitchen Display A"
    restaurant_pos_id   TEXT NOT NULL,             -- FK to the owning Restaurant POS terminal
    station_ids         TEXT NOT NULL DEFAULT '[]', -- JSON array of topology station IDs
    pairing_token_hash  TEXT NOT NULL,             -- SHA-256 of the QR enrollment token
    pairing_expires_at  TEXT NOT NULL,             -- ISO-8601 expiry timestamp
    is_active           BIGINT NOT NULL DEFAULT 1,
    last_seen_at        TEXT,                      -- nullable; NULL when never connected
    connection_status   TEXT NOT NULL DEFAULT 'disconnected'
                        CHECK (connection_status IN ('connected', 'disconnected', 'stale')),
    created_at          TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at          TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    FOREIGN KEY (restaurant_pos_id) REFERENCES terminals(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "memo_recipients" (
    id               TEXT PRIMARY KEY,
    memo_id          TEXT NOT NULL REFERENCES memos(id) ON DELETE CASCADE,
    terminal_id      TEXT NOT NULL REFERENCES terminals(id) ON DELETE RESTRICT,
    user_id          TEXT,
    delivery_status  TEXT NOT NULL DEFAULT 'pending'
                     CHECK (delivery_status IN ('pending','delivered','acknowledged')),
    delivered_at     TEXT,
    acknowledged_at  TEXT,
    acknowledged_by  TEXT,
    tenant_id        TEXT NOT NULL DEFAULT 'default',
    UNIQUE (memo_id, terminal_id)
);

CREATE TABLE IF NOT EXISTS kds_routing_rules (
    id                 TEXT PRIMARY KEY,          -- UUID v7
    restaurant_pos_id  TEXT NOT NULL,             -- FK to the owning Restaurant POS terminal
    priority           BIGINT NOT NULL,          -- lower number = higher priority; ranks rules per line
    matcher_kind       TEXT NOT NULL
                       CHECK (matcher_kind IN ('sku', 'category', 'tag')),
    matcher_value      TEXT NOT NULL,             -- SKU string or category id, per matcher_kind
    target_station     TEXT NOT NULL,             -- topology station the matched line routes to
    is_active          BIGINT NOT NULL DEFAULT 1,
    created_at         TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at         TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    FOREIGN KEY (restaurant_pos_id) REFERENCES terminals(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "user_workspace_instances" (
    user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    instance_id  TEXT NOT NULL REFERENCES "workspace_instances"(id) ON DELETE CASCADE,
    is_default   BIGINT NOT NULL DEFAULT 0,
    created_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    UNIQUE(user_id, instance_id)
);

CREATE TABLE IF NOT EXISTS workspace_inventory_locations (
    id                   TEXT PRIMARY KEY,
    instance_id          TEXT NOT NULL REFERENCES workspace_instances(id) ON DELETE CASCADE,
    location_id          TEXT NOT NULL REFERENCES inventory_locations(id) ON DELETE RESTRICT,
    is_primary           BIGINT NOT NULL DEFAULT 0
                         CHECK (is_primary IN (0, 1)),
    allow_negative_stock BIGINT NOT NULL DEFAULT 0
                         CHECK (allow_negative_stock IN (0, 1)),
    sort_order           BIGINT NOT NULL DEFAULT 0,
    UNIQUE(instance_id, location_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_ws_inv_locations_one_primary_per_instance
    ON workspace_inventory_locations(instance_id) WHERE is_primary = 1;

CREATE TABLE IF NOT EXISTS inventory (
    product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    qty        BIGINT NOT NULL DEFAULT 0 CHECK (qty >= 0),
    updated_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), location_id TEXT
    NOT NULL DEFAULT '01926b3a-0000-7000-8000-000000000001'
    REFERENCES inventory_locations(id) ON DELETE RESTRICT,
    PRIMARY KEY (product_id)
);

CREATE TABLE IF NOT EXISTS product_modifier_groups (
    product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    group_id   TEXT NOT NULL REFERENCES modifier_groups(id) ON DELETE CASCADE,
    PRIMARY KEY (product_id, group_id)
);

CREATE TABLE IF NOT EXISTS product_recipes (
    id                    TEXT PRIMARY KEY,
    parent_product_id     TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    ingredient_product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    quantity_required     BIGINT NOT NULL CHECK (quantity_required > 0),
    unit                  TEXT NOT NULL DEFAULT 'pcs',
    created_at            TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at            TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    UNIQUE (parent_product_id, ingredient_product_id)
);

CREATE TABLE IF NOT EXISTS stock_summary (
    item_id     TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    location_id TEXT NOT NULL DEFAULT '01926b3a-0000-7000-8000-000000000001'
                REFERENCES inventory_locations(id) ON DELETE RESTRICT,
    qty         BIGINT NOT NULL DEFAULT 0,
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    PRIMARY KEY (item_id, location_id)
);

CREATE TABLE IF NOT EXISTS stock_thresholds (
    id          TEXT PRIMARY KEY,                              -- UUID v7
    product_id  TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    location_id TEXT REFERENCES inventory_locations(id) ON DELETE CASCADE,
    threshold   BIGINT NOT NULL CHECK (threshold >= 0),
    enabled     BIGINT NOT NULL DEFAULT 1,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    UNIQUE(product_id, location_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_stock_thresholds_global
    ON stock_thresholds(product_id) WHERE location_id IS NULL;

CREATE TABLE IF NOT EXISTS "product_variants" (
    id              TEXT PRIMARY KEY,
    parent_sku      TEXT NOT NULL,
    name            TEXT NOT NULL,
    sku             TEXT NOT NULL UNIQUE,
    price_minor     BIGINT,
    currency        TEXT,
    barcode         TEXT,
    sort_order      BIGINT NOT NULL DEFAULT 0,
    is_active       BIGINT NOT NULL DEFAULT 1,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    tenant_id TEXT NOT NULL DEFAULT 'default',
    FOREIGN KEY (tenant_id, parent_sku) REFERENCES products(tenant_id, sku) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_product_variants_barcode ON product_variants(barcode);

CREATE TABLE IF NOT EXISTS "product_bundles" (
    id          TEXT PRIMARY KEY,
    bundle_sku  TEXT NOT NULL UNIQUE,
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    bundle_price_minor BIGINT,
    currency    TEXT NOT NULL DEFAULT 'USD',
    active      BIGINT NOT NULL DEFAULT 1,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    tenant_id TEXT NOT NULL DEFAULT 'default',
    FOREIGN KEY (tenant_id, bundle_sku) REFERENCES products(tenant_id, sku)
);

CREATE TABLE IF NOT EXISTS product_images (
    product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    slot       BIGINT NOT NULL CHECK (slot BETWEEN 1 AND 5),
    hash       TEXT NOT NULL,
    position   BIGINT NOT NULL DEFAULT 0,   -- display order of alternatives
    updated_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    PRIMARY KEY (product_id, slot)
);

CREATE TABLE IF NOT EXISTS category_taxes (
    category_id TEXT NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
    tax_rate_id TEXT NOT NULL REFERENCES tax_rates(id) ON DELETE CASCADE,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    PRIMARY KEY (category_id, tax_rate_id)
);

CREATE TABLE IF NOT EXISTS "product_taxes" (
    product_sku  TEXT NOT NULL,
    tax_rate_id  TEXT NOT NULL REFERENCES tax_rates(id) ON DELETE CASCADE,
    created_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    tenant_id TEXT NOT NULL DEFAULT 'default',
    PRIMARY KEY (product_sku, tax_rate_id),
    FOREIGN KEY (tenant_id, product_sku) REFERENCES products(tenant_id, sku) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS payable_payments (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL,
    payable_id      TEXT NOT NULL REFERENCES payables(id) ON DELETE CASCADE,
    amount_minor    BIGINT NOT NULL CHECK (amount_minor > 0),
    currency        TEXT NOT NULL DEFAULT 'IDR',
    method          TEXT NOT NULL DEFAULT 'cash',
    paid_at         TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    recorded_by     TEXT,
    note            TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS gift_card_transactions (
    id                  TEXT PRIMARY KEY,
    gift_card_id        TEXT NOT NULL REFERENCES gift_cards(id),
    sale_id             TEXT REFERENCES sales(id),
    txn_type            TEXT NOT NULL CHECK (txn_type IN ('issue', 'redeem', 'topup', 'refund')),
    amount_minor        BIGINT NOT NULL,
    balance_after_minor BIGINT NOT NULL,
    notes               TEXT NOT NULL DEFAULT '',
    created_at          TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_gift_card_redeem_sale
    ON gift_card_transactions(gift_card_id, sale_id)
    WHERE txn_type = 'redeem' AND sale_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS "kds_orders" (
    id              TEXT PRIMARY KEY,
    -- One order per sale AND kitchen zone: a sale with items in multiple
    -- zones fans out into one ticket per zone (multi-KDS routing), so the
    -- uniqueness key is the (sale, zone) pair, not the sale alone.
    sale_id         TEXT NOT NULL REFERENCES sales(id),
    -- Valid states: pending (received, not started), preparing,
    -- ready (cooked, awaiting pickup), served (delivered),
    -- cancelled (voided by kitchen or POS).
    status          TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'preparing', 'ready', 'served', 'cancelled')),
    items_summary   TEXT NOT NULL DEFAULT '',
    item_count      BIGINT NOT NULL DEFAULT 0,
    display_number  BIGINT,
    received_at     TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    started_at      TEXT,
    ready_at        TEXT,
    served_at       TEXT,
    prep_time_seconds BIGINT DEFAULT 0,
    notes           TEXT NOT NULL DEFAULT ''
, store_id TEXT, kitchen_zone TEXT, table_number TEXT, priority BIGINT NOT NULL DEFAULT 0, target_instance_id TEXT, restaurant_pos_id TEXT, acked_by_device TEXT, acked_at TEXT, ticket_prefix TEXT NOT NULL DEFAULT '',
    UNIQUE (sale_id, kitchen_zone));

CREATE TABLE IF NOT EXISTS loyalty_transactions (
    id          TEXT PRIMARY KEY,
    account_id  TEXT NOT NULL REFERENCES loyalty_accounts(id),
    sale_id     TEXT REFERENCES sales(id),
    points      BIGINT NOT NULL,
    txn_type    TEXT NOT NULL,
    description TEXT NOT NULL,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_loyalty_earn_sale
    ON loyalty_transactions(account_id, sale_id)
    WHERE sale_id IS NOT NULL AND txn_type = 'earn';

CREATE UNIQUE INDEX IF NOT EXISTS uq_loyalty_redeem_sale
    ON loyalty_transactions(account_id, sale_id)
    WHERE sale_id IS NOT NULL AND txn_type = 'redeem';

CREATE TABLE IF NOT EXISTS payments (
    id          TEXT PRIMARY KEY,
    sale_id     TEXT NOT NULL REFERENCES sales(id) ON DELETE CASCADE,
    method      TEXT NOT NULL,
    amount_minor BIGINT NOT NULL,
    currency    TEXT NOT NULL,
    created_at  TEXT NOT NULL
, gateway_reference TEXT, gateway_status TEXT, gateway_response TEXT, settled_at TEXT, settled_by TEXT, idempotency_key TEXT);

CREATE UNIQUE INDEX IF NOT EXISTS idx_payments_idempotency_key ON payments(idempotency_key);

CREATE TABLE IF NOT EXISTS promotion_applications (
    id          TEXT PRIMARY KEY,
    promotion_id TEXT NOT NULL REFERENCES promotions(id),
    sale_id     TEXT NOT NULL REFERENCES sales(id),
    discount_minor BIGINT NOT NULL,
    description TEXT NOT NULL,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS receipt_barcodes (
    id          TEXT PRIMARY KEY,
    sale_id     TEXT NOT NULL REFERENCES sales(id),
    barcode     TEXT NOT NULL UNIQUE,
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS refunds (
    id              TEXT PRIMARY KEY,
    sale_id         TEXT NOT NULL REFERENCES sales(id) ON DELETE RESTRICT,
    total_minor     BIGINT NOT NULL CHECK (total_minor >= 0),
    currency        TEXT NOT NULL,
    reason          TEXT NOT NULL DEFAULT '',
    note            TEXT NOT NULL DEFAULT '',
    processed_by    TEXT NOT NULL,          -- user_id who processed the refund
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, tenant_id TEXT NOT NULL DEFAULT 'default');

CREATE TABLE IF NOT EXISTS "sale_lines" (
    id            TEXT PRIMARY KEY,
    sale_id       TEXT NOT NULL REFERENCES sales(id) ON DELETE CASCADE,
    sku           TEXT NOT NULL,
    qty           BIGINT NOT NULL CHECK (qty > 0),
    unit_minor    BIGINT NOT NULL,
    line_minor    BIGINT NOT NULL,
    currency      TEXT NOT NULL,
    line_position BIGINT NOT NULL,
    tax_minor     BIGINT NOT NULL DEFAULT 0,
    tax_rate_id   TEXT REFERENCES tax_rates(id),
    serial_number TEXT,
    store_id      TEXT REFERENCES "locations"(id) ON DELETE SET NULL ON UPDATE CASCADE,
    course        TEXT,
    modifiers_json TEXT,
    tax_breakdown_json TEXT, cost_minor BIGINT, tenant_id TEXT NOT NULL DEFAULT 'default', product_id TEXT, product_name TEXT, category_id TEXT,
    UNIQUE (sale_id, line_position)
);

CREATE TABLE IF NOT EXISTS tables (
    id              TEXT PRIMARY KEY,
    name            TEXT NOT NULL,
    capacity        BIGINT NOT NULL DEFAULT 4,
    pos_x           DOUBLE PRECISION NOT NULL DEFAULT 0,
    pos_y           DOUBLE PRECISION NOT NULL DEFAULT 0,
    shape           TEXT NOT NULL DEFAULT 'circle',
    width           DOUBLE PRECISION NOT NULL DEFAULT 10,
    height          DOUBLE PRECISION NOT NULL DEFAULT 10,
    status          TEXT NOT NULL DEFAULT 'available',
    active_sale_id  TEXT REFERENCES sales(id),
    section         TEXT NOT NULL DEFAULT '',
    active          BIGINT NOT NULL DEFAULT 1,
    sort_order      BIGINT NOT NULL DEFAULT 0,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS cash_payouts (
    id          TEXT PRIMARY KEY,
    shift_id    TEXT NOT NULL REFERENCES shifts(id),
    amount_minor BIGINT NOT NULL CHECK(amount_minor > 0),
    reason      TEXT NOT NULL DEFAULT '',
    created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS inventory_transactions (
    id                TEXT PRIMARY KEY,                              -- UUID v7
    type              TEXT NOT NULL CHECK (type IN (
                          'receive',        -- goods received (from supplier or PO)
                          'transfer-out',   -- goods sent to another location
                          'transfer-in',    -- goods received from another location
                          'adjust',         -- manual stock correction
                          'count',          -- stock take / physical count
                          'sale',           -- POS sale deduction (ADR-19 §2)
                          'void',           -- sale void compensating credit (ADR-19 §5.3)
                          'refund',         -- sale refund compensating credit (ADR-19 §5.3)
                          'transfer',       -- generic stock transfer
                          'purchase-order-receive', -- PO receipt
                          'stock-count',    -- inventory stock-take / physical count
                          'manual-adjustment' -- manager override adjustment
                      )),
    location_id       TEXT NOT NULL REFERENCES inventory_locations(id) ON DELETE RESTRICT,
    staff_id          TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    transfer_id       TEXT REFERENCES stock_transfers(id),            -- nullable; set for transfer types
    purchase_order_id TEXT REFERENCES purchase_orders(id),            -- nullable; set for PO receiving
    notes             TEXT NOT NULL DEFAULT '',
    created_at        TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, inventory_shift_id TEXT
    REFERENCES inventory_shifts(id));

CREATE TABLE IF NOT EXISTS stock_transfer_lines (
    id           TEXT PRIMARY KEY,
    transfer_id  TEXT NOT NULL REFERENCES stock_transfers(id) ON DELETE CASCADE,
    sku          TEXT NOT NULL,
    product_name TEXT NOT NULL DEFAULT '',
    qty          BIGINT NOT NULL CHECK (qty > 0),
    received_qty BIGINT NOT NULL DEFAULT 0 CHECK (received_qty >= 0)
);

CREATE TABLE IF NOT EXISTS stock_alert_events (
    id              TEXT PRIMARY KEY,
    threshold_id    TEXT NOT NULL REFERENCES stock_thresholds(id) ON DELETE CASCADE,
    product_id      TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    location_id     TEXT REFERENCES inventory_locations(id) ON DELETE CASCADE,
    current_qty     BIGINT NOT NULL,                         -- qty at trigger time
    threshold       BIGINT NOT NULL,                         -- threshold value that was breached
    status          TEXT NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active', 'acknowledged', 'resolved')),
    triggered_at    TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    acknowledged_at TEXT,
    acknowledged_by TEXT REFERENCES users(id),
    resolved_at     TEXT
);

CREATE TABLE IF NOT EXISTS "bundle_items" (
    id          TEXT PRIMARY KEY,
    bundle_id   TEXT NOT NULL REFERENCES product_bundles(id),
    sku         TEXT NOT NULL,
    qty         BIGINT NOT NULL DEFAULT 1,
    unit_price_minor BIGINT,
    tenant_id TEXT NOT NULL DEFAULT 'default',
    FOREIGN KEY (tenant_id, sku) REFERENCES products(tenant_id, sku)
);

CREATE TABLE IF NOT EXISTS kds_line_items (
    id              TEXT PRIMARY KEY,                              -- UUIDv7
    kds_order_id    TEXT NOT NULL REFERENCES kds_orders(id) ON DELETE CASCADE,
    sku             TEXT NOT NULL,
    display_name    TEXT NOT NULL,                                 -- product name at creation time
    qty             BIGINT NOT NULL CHECK(qty > 0),
    course          TEXT,                                          -- NULL | "appetizer" | "main" | "dessert" | "beverage"
    modifiers_json  TEXT,                                          -- NULL | JSON array of { name, choice, price_minor }
    line_position   BIGINT NOT NULL DEFAULT 0,
    item_status     TEXT NOT NULL DEFAULT 'pending'
                    CHECK(item_status IN ('pending','preparing','ready','served','cancelled')),
    started_at      TEXT,
    ready_at        TEXT,
    served_at       TEXT,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, restaurant_pos_id TEXT);

CREATE TABLE IF NOT EXISTS kds_order_targets (
    kds_order_id     TEXT NOT NULL REFERENCES kds_orders(id) ON DELETE CASCADE,
    target_instance_id TEXT NOT NULL,
    created_at       TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), restaurant_pos_id TEXT,
    PRIMARY KEY (kds_order_id, target_instance_id)
);

CREATE TABLE IF NOT EXISTS refund_lines (
    id              TEXT PRIMARY KEY,
    refund_id       TEXT NOT NULL REFERENCES refunds(id) ON DELETE CASCADE,
    sale_line_id    TEXT NOT NULL,          -- FK to sale_lines.id (logical ref, no CASCADE)
    sku             TEXT NOT NULL,
    qty             BIGINT NOT NULL CHECK (qty > 0),
    unit_minor      BIGINT NOT NULL CHECK (unit_minor >= 0),
    line_minor      BIGINT NOT NULL CHECK (line_minor >= 0),
    currency        TEXT NOT NULL,
    created_at      TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE IF NOT EXISTS inventory_transaction_lines (
    id               TEXT PRIMARY KEY,                               -- UUID v7
    transaction_id   TEXT NOT NULL REFERENCES inventory_transactions(id) ON DELETE CASCADE,
    sku              TEXT NOT NULL,
    product_name     TEXT NOT NULL DEFAULT '',
    qty              BIGINT NOT NULL CHECK (qty > 0),
    barcode_scanned  TEXT,                                           -- nullable; the barcode actually scanned
    sort_order       BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS stock_movements (
    id                  TEXT PRIMARY KEY,        -- UUID v4
    item_id             TEXT NOT NULL,           -- product ID (FK to products.id)
    delta               BIGINT NOT NULL,        -- +N or -N
    reason              TEXT,                    -- 'sale', 'restock', 'correction', 'stock-take', etc.
    source_terminal_id  TEXT,                    -- terminal that performed the operation
    source_user_id      TEXT,                    -- user who performed the operation
    created_at          TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, store_id TEXT NOT NULL DEFAULT '', location_id TEXT
    NOT NULL DEFAULT '01926b3a-0000-7000-8000-000000000001'
    REFERENCES inventory_locations(id) ON DELETE RESTRICT, inventory_transaction_id TEXT
    REFERENCES inventory_transactions(id) ON DELETE RESTRICT);

CREATE TABLE IF NOT EXISTS stock_movements_archive (
    id                  TEXT PRIMARY KEY,
    item_id             TEXT NOT NULL,
    delta               BIGINT NOT NULL,
    reason              TEXT,
    source_terminal_id  TEXT,
    source_user_id      TEXT,
    store_id            TEXT NOT NULL DEFAULT '',
    created_at          TEXT NOT NULL
, location_id TEXT
    NOT NULL DEFAULT '01926b3a-0000-7000-8000-000000000001'
    REFERENCES inventory_locations(id) ON DELETE RESTRICT, inventory_transaction_id TEXT
    REFERENCES inventory_transactions(id) ON DELETE RESTRICT);

CREATE OR REPLACE FUNCTION audit_log_immutable_delete_fn() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM settings WHERE key = 'audit.retention_sweep_active'
    ) THEN
        RAISE EXCEPTION 'audit_log entries are immutable: DELETE not allowed';
    END IF;
    RETURN NULL;
END;
$$;

CREATE OR REPLACE TRIGGER audit_log_immutable_delete
    BEFORE DELETE ON audit_log
    FOR EACH ROW EXECUTE FUNCTION audit_log_immutable_delete_fn();

CREATE OR REPLACE FUNCTION audit_log_immutable_update_fn() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_log entries are immutable: UPDATE not allowed';
END;
$$;

CREATE OR REPLACE TRIGGER audit_log_immutable_update
    BEFORE UPDATE ON audit_log
    FOR EACH ROW EXECUTE FUNCTION audit_log_immutable_update_fn();

CREATE OR REPLACE FUNCTION loyalty_tiers_validate_fn() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF trim(NEW.name) = ''
       OR NEW.min_points < 0
       OR NEW.points_per_unit <= 0
       OR NEW.earn_multiplier_millionths <= 0
       OR length(NEW.colour) <> 7
       OR substr(NEW.colour, 1, 1) <> '#'
       OR NEW.colour !~ '^#[0-9A-Fa-f]{6}$'
    THEN
        RAISE EXCEPTION 'invalid loyalty tier configuration';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE TRIGGER loyalty_tiers_validate_insert
    BEFORE INSERT ON loyalty_tiers
    FOR EACH ROW EXECUTE FUNCTION loyalty_tiers_validate_fn();

CREATE OR REPLACE TRIGGER loyalty_tiers_validate_update
    BEFORE UPDATE OF name, min_points, points_per_unit, earn_multiplier_millionths, colour
    ON loyalty_tiers
    FOR EACH ROW EXECUTE FUNCTION loyalty_tiers_validate_fn();

CREATE OR REPLACE FUNCTION assignments_scope_id_pair_fn() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.scope_type = 'organization') != (NEW.scope_id IS NULL) THEN
        RAISE EXCEPTION 'assignments: scope_id must be NULL exactly when scope_type is organization';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE TRIGGER trg_assignments_scope_id_pair
    AFTER INSERT ON assignments
    FOR EACH ROW EXECUTE FUNCTION assignments_scope_id_pair_fn();

CREATE OR REPLACE TRIGGER trg_assignments_scope_id_pair_update
    AFTER UPDATE OF scope_type, scope_id ON assignments
    FOR EACH ROW EXECUTE FUNCTION assignments_scope_id_pair_fn();

